<template><section aria-label="文件校验工具"><p class="tool-note">分块计算 SHA-256，文件不上传。计算在后台线程运行，可取消；对比时忽略摘要字母大小写。</p><label class="tool-label">选择待校验文件<input type="file" aria-label="选择待校验文件" @change="selectFile" /></label><p v-if="file">{{ file.name }} · {{ sizeLabel }}</p><div class="tool-actions"><button type="button" :disabled="!file || busy" @click="start">计算 SHA-256</button><button type="button" :disabled="!busy" @click="cancel">取消校验</button></div><div v-if="busy" class="tool-label"><progress :value="progress" max="100" aria-label="文件校验进度"></progress><span>{{ progress }}%</span></div><label class="tool-label">SHA-256 结果<textarea class="hash-result" :value="digest" readonly aria-label="SHA-256 结果" spellcheck="false"></textarea></label><button type="button" :disabled="!digest" @click="copy">复制 SHA-256</button><label class="tool-label">预期 SHA-256（可选）<input v-model="expected" aria-label="预期 SHA-256" placeholder="粘贴 64 位十六进制摘要" spellcheck="false" /></label><p v-if="comparison" :class="comparison.ok ? 'tool-success' : 'tool-error'" role="status">{{ comparison.text }}</p><p role="status">{{ message }}</p></section></template>
<script>
import { formatBytes } from '../../utils/utility-tools.mjs';
export default { name: 'HashTool', data: () => ({ file: null, digest: '', expected: '', busy: false, progress: 0, message: '', hashWorker: null }), computed: { sizeLabel() { return this.file ? formatBytes(this.file.size) : ''; }, comparison() { const value = this.expected.trim(); if (!value) return null; if (!/^[a-f\d]{64}$/i.test(value)) return { ok: false, text: '预期摘要应为 64 位十六进制字符' }; if (!this.digest) return { ok: false, text: '请先计算文件摘要' }; const ok = value.toLowerCase() === this.digest; return { ok, text: ok ? '校验一致：文件摘要匹配' : '校验不一致：文件摘要不同' }; } }, beforeUnmount() { this.cancel(); }, methods: { selectFile(event) { this.cancel(); this.file = event.target.files?.[0] || null; this.digest = ''; this.progress = 0; this.message = ''; event.target.value = ''; }, start() { if (!this.file || this.busy) return; this.digest = ''; this.progress = 0; this.busy = true; this.message = '正在计算…'; try { const worker = new Worker(new URL('../../utils/file-hash.worker.mjs', import.meta.url)); this.hashWorker = worker; worker.onmessage = event => { if (this.hashWorker !== worker) return; const data = event.data; if (data.type === 'progress') this.progress = data.total ? Math.floor(data.processed / data.total * 100) : 100; if (data.type === 'done') { this.digest = data.digest; this.progress = 100; this.busy = false; this.message = 'SHA-256 计算完成'; worker.terminate(); this.hashWorker = null; } if (data.type === 'error') { this.cancel(); this.message = '计算失败：' + data.message; } }; worker.onerror = () => { this.cancel(); this.message = '后台计算失败，请重试'; }; worker.postMessage({ file: this.file }); } catch { this.cancel(); this.message = '后台线程未启动，请重试或使用支持 Worker 的浏览器'; } }, cancel() { const wasBusy = this.busy; this.hashWorker?.terminate(); this.hashWorker = null; this.busy = false; if (wasBusy) this.message = '已取消校验'; }, async copy() { try { await navigator.clipboard.writeText(this.digest); this.message = '已复制 SHA-256'; } catch { this.message = '复制未完成，请选中摘要手动复制'; } } } };
</script>
